252				out, err := ExportUpstreamLineage(tc.graph, tc.target)
253				if err == nil {
254					t.Fatalf("ExportUpstreamLineage(%q) succeeded with %q, want error %q",
255						tc.target, out, tc.wantErr)
256				}
257				if err.Error() != tc.wantErr {
258					t.Errorf("error = %q, want %q", err, tc.wantErr)
259				}
260				if out != "" {
261					t.Errorf("failed export returned partial content %q, want empty string", out)
262				}
263			})
264		}
265		assertGraphUnchanged(t, before, graph)
266	}
267	
268	// A failed export leaves the graph exactly as it was, and a successful one
269	// does too — checked over nodes, both edge directions and list orders.
270	func TestExportUpstreamLineageReadOnly(t *testing.T) {
271		graph := buildRegisteredGraph(t, [][]string{
272			{"raw"},
273			{"a", "raw"},
274			{"b", "raw"},
275			{"mid", "b"},
276			{"report", "raw", "a", "mid"},
